export const AUTO_DETECT_CODE = 'AUTO';
export const CUSTOM_EPSG_CODE = 'CUSTOM';

export const ALL_OPTIONS = [
  { code: AUTO_DETECT_CODE, label: 'Auto-detect from coordinates', group: 'Special' },
  { code: CUSTOM_EPSG_CODE, label: 'Custom EPSG code (lookup via epsg.io)...', group: 'Special' },
  ...PROJECTIONS,
];

/**
 * Fetch a proj4 string for any EPSG code from epsg.io.
 * Used when the user enters a custom code not in the static list.
 * Returns null on failure.
 */
export async function fetchProj4FromEpsgIo(epsgCode) {
  const code = String(epsgCode).replace(/^EPSG:/i, '');
  try {
    const res = await fetch(`https://epsg.io/${code}.proj4`);
    if (!res.ok) return null;
    const text = (await res.text()).trim();
    if (!text || text.startsWith('<')) return null;
    return text;
  } catch {
    return null;
  }
}

/**
 * Given a sample X and Y, return the best-matching entry from PROJECTIONS.
 * Checks xRange and yRange; returns null if nothing matches.
 */
export function detectProjection(x, y) {
  // WGS84 passthrough check first
  if (x >= -180 && x <= 180 && y >= -90 && y <= 90) {
    return PROJECTIONS.find(p => p.code === 'EPSG:4326') || null;
  }
  return PROJECTIONS.find(
    p => p.xRange && x >= p.xRange[0] && x <= p.xRange[1]
      && p.yRange && y >= p.yRange[0] && y <= p.yRange[1]
  ) || null;
}

/**
 * Convert [x, y] from the given proj4def to WGS84 [lng, lat].
 * Pass proj4 library instance as first arg.
 */
export function toWgs84(proj4lib, proj4def, x, y) {
  if (!proj4def) return [x, y]; // already WGS84
  return proj4lib(proj4def, 'WGS84', [x, y]);
}

/**
 * validateCoords — bounds checking removed (users may legitimately work
 * across zone boundaries). Always returns valid; kept for API compatibility.
 */
export function validateCoords(x, y, epsgCode, swapXY) {
  if (x == null || y == null || !epsgCode) {
    return { ok: false, message: 'Missing coordinates or projection.' };
  }
  return { ok: true, message: 'Coordinates accepted.' };
}